#include <iostream>
#include <vector>
#include <set>
#include <fstream>
using namespace std;long long modpow(long long a,int b,int p){long long r=1;while(b){if(b%2)r=r*a%p;a=a*a%p;b/=2;}return r;}bool prime(int x){if(x<2)return false;for(int d=2;1LL*d*d<=x;d++)if(x%d==0)return false;return true;}
int main(int argc,char**argv){ifstream f(argv[1]);int L,p,t;long long claimed;f>>L>>p>>t>>claimed;if(!prime(p)||t!=L*(L-1)+1)return 2;vector<int>a;for(int x=2;a.size()<L;x++)if(prime(x))a.push_back(x);if(p<=2LL*a.back()*a.back())return 3;set<int>core;for(int i=0;i<L;i++)for(int j=0;j<i;j++){int v=a[i]*a[j]%p;core.insert(v);core.insert(p-v);}if(core.size()!=L*(L-1))return 4;vector<int>cnt(p),owner(p,-1),iv;for(int b:a)iv.push_back(modpow(b*b,p-2,p));set<int>nodes;for(int k=0;k<t;k++){int x;f>>x;if(!f||x<=0||x>=p||core.count(x)||!nodes.insert(x).second)return 5;long long x2=1LL*x*x%p,x3=x2*x%p,x4=x2*x2%p,den=modpow(x3,p-2,p);set<int>local;for(int i=0;i<L;i++){long long val=(x2*iv[i]+1LL*a[i]*a[i])%p;int z=(val-x4+p)*den%p;if(z<2||!local.insert(z).second)return 6;cnt[z]++;if(owner[z]==-1)owner[z]=i;else if(owner[z]!=i)owner[z]=-2;}}long long ownersingle=0;for(int o:owner)ownersingle+=o>=0;long long singles=0,distinct=0,total=0;for(int c:cnt){singles+=c==1;distinct+=c>0;total+=c;}if(singles!=claimed||total!=1LL*L*t)return 7;cout<<"{\"pass\":true,\"L\":"<<L<<",\"p\":"<<p<<",\"singletons\":"<<singles<<",\"singleton_lists\":"<<ownersingle<<",\"distinct\":"<<distinct<<",\"incidences\":"<<total<<"}\n";}
